def solve():
    input = sys.stdin.read
    data = input().split()

    if not data:
        return

    iterator = iter(data)
    try:
        N = int(next(iterator))
        M = int(next(iterator))

        A = []
        for _ in range(N):
            A.append(next(iterator))

        B = []
        for _ in range(M):
            B.append(next(iterator))
    except StopIteration:
        return

    # Convert B to a list of lists for easier indexing
    B_grid = [list(row) for row in B]

    # Iterate over all possible top-left positions (r, c) in A
    # The template B of size MxM can start at row r and column c
    # where 0 <= r <= N - M and 0 <= c <= N - M
    for r in range(N - M + 1):
        for c in range(N - M + 1):
            match = True
            # Check if the MxM subgrid of A starting at (r, c) matches B
            for i in range(M):
                for j in range(M):
                    # If B has a black pixel ('#'), A must also have a black pixel at the corresponding position
                    if B_grid[i][j] == '#':
                        if A[r + i][c + j] != '#':
                            match = False
                            break
                if not match:
                    break
            if match:
                print("Yes")
                return

    print("No")

